SELECT 
FROM et_user_exam_history

    histId = #{histId}
    AND user_id = #{userId}
    AND exam_paper_id = #{examPaperId}

        AND content LIKE CONCAT('%', #{content}, '%')


        AND submit_time = #{submitTime}


        AND point_get = #{pointGet}


        AND duration = #{duration}


ORDER BY create_time DESC

SELECT 
FROM et_user_exam_history

    histId = #{condition.histId}
    AND user_id = #{condition.userId}
    AND exam_paper_id = #{condition.examPaperId}

        AND content LIKE CONCAT('%', #{condition.content}, '%')


        AND submit_time = #{condition.submitTime}


        AND point_get = #{condition.pointGet}


        AND duration = #{condition.duration}


ORDER BY create_time DESC
LIMIT #{offset}, #{pageSize}

SELECT COUNT(*)
FROM et_user_exam_history

    histId = #{histId}
    AND user_id = #{userId}
    AND exam_paper_id = #{examPaperId}

        AND content LIKE CONCAT('%', #{content}, '%')


        AND submit_time = #{submitTime}


        AND point_get = #{pointGet}


        AND duration = #{duration}

